using HakutaiKagami.Core.World;
using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class SurveyRoadReviewTests
{
    // Synthetic proof fixture only. These coordinates are not Futamurayama or historical evidence.
    static SurveyRoadCandidate SyntheticSurvey()=>SurveyRoadReview.Futamura() with{EndpointsIdentified=true,AlignmentIdentified=true,CoordinateFrame=JapanGeography.Projection,Datum="JGD2011",HistoricalPeriodSupported=true,CoordinateControlVerified=true,IndependentCheckPassed=true,MaximumErrorMm=1000,MetricVertices=[new(0,0),new(100000,0),new(100000,100000)],Sources=[new("fixture","https://example.test/survey",new string('a',64),"survey-coordinate-table")]};
    [Fact] public void RealDesignationImageIsRecordedWithoutInventingWorldCoordinates(){var c=SurveyRoadReview.Futamura();Assert.Equal(9,c.PixelVertices.Length);Assert.Equal(new SurveyMapPixel(489,214),c.PixelVertices[0]);Assert.Empty(c.MetricVertices);Assert.Null(c.Datum);Assert.Null(c.MaximumErrorMm);var d=SurveyRoadReview.Evaluate(c,1560);Assert.False(d.CanReplace);Assert.Contains("world-coordinate-reference-missing",d.Reasons);Assert.Contains("coordinate-control-not-verified",d.Reasons);Assert.Contains("target-era-alignment-unproven",d.Reasons);Assert.Throws<InvalidDataException>(()=>SurveyRoadReview.Replacement(c,1560));}
    [Fact] public void ASourceHashAndPinkBoundaryDoNotAuthorizeAWorldReplacement(){var c=SurveyRoadReview.Futamura() with{HistoricalPeriodSupported=true,EndpointsIdentified=true,AlignmentIdentified=true};Assert.False(SurveyRoadReview.Evaluate(c,1560).CanReplace);}
    [Theory][InlineData("image-pixels")][InlineData("unknown")][InlineData("EPSG:3857")]
    public void WrongCoordinateUnitsAreRejected(string frame)=>Assert.False(SurveyRoadReview.Evaluate(SyntheticSurvey() with{CoordinateFrame=frame},1560).CanReplace);
    [Theory][InlineData(-1)][InlineData(5001)][InlineData(50000)]
    public void InvalidOrExcessiveCoordinateErrorIsRejected(long mm)=>Assert.False(SurveyRoadReview.Evaluate(SyntheticSurvey() with{MaximumErrorMm=mm},1560).CanReplace);
    [Fact] public void WrongYearMissingIndependentCheckOrEraEvidenceRejects(){var c=SyntheticSurvey();Assert.False(SurveyRoadReview.Evaluate(c,1600).CanReplace);Assert.False(SurveyRoadReview.Evaluate(c with{IndependentCheckPassed=false},1560).CanReplace);Assert.False(SurveyRoadReview.Evaluate(c with{HistoricalPeriodSupported=false},1560).CanReplace);Assert.False(SurveyRoadReview.Evaluate(c with{Datum=null},1560).CanReplace);}
    [Fact] public void LocatorOnlySourceCannotBecomeSurveyAuthority(){var c=SyntheticSurvey();Assert.False(SurveyRoadReview.Evaluate(c with{Sources=[c.Sources[0] with{Role="representative-locator"}]},1560).CanReplace);Assert.False(SurveyRoadReview.Evaluate(c with{Sources=[c.Sources[0] with{Sha256="invalid"}]},1560).CanReplace);}
    [Fact] public void SyntheticVerifiedBentLineUsesAllSegmentsNotEndpointChord(){var c=SyntheticSurvey();Assert.True(SurveyRoadReview.Evaluate(c,1560).CanReplace);var g=SurveyRoadReview.Replacement(c,1560);Assert.Equal(200000,g.TotalLengthMm);Assert.Equal(new long[]{100000,100000},g.SegmentLengthsMm);Assert.Equal(ContractJson.CanonicalHash(c),g.EvidenceHash);}
    [Fact] public void EvidenceAndPixelTraceChangesInvalidateTheReviewFingerprint(){var c=SurveyRoadReview.Futamura();var d=SurveyRoadReview.Evaluate(c,1560);Assert.NotEqual(d.EvidenceHash,SurveyRoadReview.Evaluate(c with{PixelVertices=[new(488,214),..c.PixelVertices.Skip(1)]},1560).EvidenceHash);Assert.NotEqual(d.EvidenceHash,SurveyRoadReview.Evaluate(c with{Sources=[..c.Sources.Select(s=>s with{Sha256=new string('0',64)})]},1560).EvidenceHash);}
    [Fact] public void RefusalPreservesMovementDefinitionAndSaveRecovery(){var w=HistoricalRoads.Create();var defs=w.Definitions;var graph=ContractJson.CanonicalHash(HistoricalRoads.Edges);Assert.Throws<InvalidDataException>(()=>SurveyRoadReview.Replacement(SurveyRoadReview.Futamura(),1560));Assert.Equal(graph,ContractJson.CanonicalHash(HistoricalRoads.Edges));Assert.Equal(defs.Version,HistoricalRoads.Create().Definitions.Version);var s=new WorldSession(w);Assert.Equal(ResultCode.Accepted,s.Submit(HistoricalRoads.Order(w,"request:survey-review"),s.Revision).Code);s.AdvanceTo(1);var l=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs.Single(l=>l.Edge=="futamura-remnant");s.AdvanceTo(l.StartAt+100);var root=Path.Combine(Path.GetTempPath(),"hakutai-survey-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,defs);store.Save(s,"check",w.WorldId,new(.375,1));var host=new WorldSessionHost(new(HistoricalRoads.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("check"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(s.GetBranchView(ContractFixture.Officer)),ContractJson.Write(host.Current.GetBranchView(ContractFixture.Officer)));host.Current.SetPaused(false);s.AdvanceTo(100000);host.Current.AdvanceTo(100000);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Branches),ContractJson.Write(host.Current.DiagnosticSnapshot().Branches));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Couriers),ContractJson.Write(host.Current.DiagnosticSnapshot().Couriers));}
}
